#[no_mangle]
pub unsafe extern "C" fn tsvc_s351_direct_unrolled_saxpy(p:*const f64,l:usize,q:*mut f64,cap:usize)->i64{if p.is_null()||l<12||l>82{return -1}let x=unsafe{std::slice::from_raw_parts(p,l)};let rd=x[0];if !rd.is_finite()||rd.fract()!=0.0||rd<5.0||rd>40.0{return -1}let n=rd as usize;if n%5!=0||l!=2+2*n||x[1..].iter().any(|v|!v.is_finite()||v.fract()!=0.0||v.abs()>1.0){return -1}if q.is_null()||cap<n{return -2}let mut a=[0.0;40];a[..n].copy_from_slice(&x[2..2+n]);let alpha=x[1];for base in (0..n).step_by(5){let p0=alpha*x[2+n+base];a[base]=a[base]+p0;let p1=alpha*x[2+n+base+1];a[base+1]=a[base+1]+p1;let p2=alpha*x[2+n+base+2];a[base+2]=a[base+2]+p2;let p3=alpha*x[2+n+base+3];a[base+3]=a[base+3]+p3;let p4=alpha*x[2+n+base+4];a[base+4]=a[base+4]+p4;}let y=unsafe{std::slice::from_raw_parts_mut(q,n)};y.copy_from_slice(&a[..n]);n as i64}
